                    return .{ .end_pos = (uri_end + 1), .is_email = false };
                }
            }
            var email_pos = pos;
            _ = &email_pos;
            while (((email_pos < content.len) and ((((helpers.isAlphaNum(content[@as(usize, @intCast(email_pos))]) or (content[@as(usize, @intCast(email_pos))] == 46)) or (content[@as(usize, @intCast(email_pos))] == 45)) or (content[@as(usize, @intCast(email_pos))] == 95)) or (content[@as(usize, @intCast(email_pos))] == 43)))) {
                email_pos = (email_pos + 1);
            }
            if ((((email_pos < content.len) and (content[@as(usize, @intCast(email_pos))] == 64)) and (email_pos > pos))) {
                email_pos = (email_pos + 1);
                const domain_start = email_pos;
                var label_len: u32 = 0;
                _ = &label_len;
                var dot_count: u32 = 0;
                _ = &dot_count;
                var valid_domain = true;
                _ = &valid_domain;
                while (((email_pos < content.len) and ((helpers.isAlphaNum(content[@as(usize, @intCast(email_pos))]) or (content[@as(usize, @intCast(email_pos))] == 46)) or (content[@as(usize, @intCast(email_pos))] == 45)))) {
                    if ((content[@as(usize, @intCast(email_pos))] == 46)) {
                        if ((label_len == 0)) {
                            valid_domain = false;
                            break;
                        }
                        label_len = 0;
                        dot_count = (dot_count + 1);
                    } else {
                        label_len = (label_len + 1);
                        if ((label_len > 63)) {
                            valid_domain = false;
                            break;
                        }
                    }
                    email_pos = (email_pos + 1);
                }
                if (((((((valid_domain and (email_pos < content.len)) and (content[@as(usize, @intCast(email_pos))] == 62)) and (email_pos > domain_start)) and (label_len > 0)) and (dot_count > 0)) and helpers.isAlphaNum(content[@as(usize, @intCast((email_pos - 1)))]))) {
                    return .{ .end_pos = (email_pos + 1), .is_email = true };
                }
            }
        }
        return null;
}

pub fn renderAutolink(p: *Parser, url: []const u8, is_email: bool) bun.JSError!void {
        _ = try p.renderer.enterSpan(.a, .{ .href = url, .autolink = true, .autolink_email = is_email });
        _ = try p.emitText(.normal, url);
        _ = try p.renderer.leaveSpan(.a);
}
